# Settlement: nothing gets stuck, a bill sent again goes back to whoever
# rejected it, and settlement bills share the planner's duplicate register
# (17 Nov 2026). Run on the ERP the app talks to (prod), once; safe to re-run.
#
#   1. Settlement Step "decision" gets the option Skipped (on leave / left /
#      2 working days without action).
#   2. Settlement Request gets "resent_from" (the rejected request a bill was
#      sent again from).
#   3. Bill Fingerprint "kind" gets the option Bill (a settlement bill).
#   4. Server Script "Settlement API"        <- settlement_api.py
#   5. Server Script "Bill Fingerprint API"  <- bill_fingerprint_api.py
#   6. Server Script "Settlement Escalation" (Scheduler Event, hourly at :20)
#                                            <- settlement_escalation.py
# Sources: share/src/app/expense-claims/server/ and share/src/app/field-expense/server/.
#
# Paste into ERP > System Console (type Python), logged in as a System Manager.
# 1) DRY = True, "Commit" unticked: only prints.  2) DRY = False, tick Commit.
# Then Clear Cache (the new options and field).

DRY = True
W = "WOULD " if DRY else ""
API = '# Server Script "Settlement API" -- type API, method settlement (16 Nov 2026).\n# Settlement approval: a request goes up the requester\'s reporting line --\n# BE > ABM > RBM > SM/ZSM > GM > CEO -- one approver at a time; the CEO\'s\n# approval is final. Every action goes through here (reps and approvers have\n# no DocType permission on Settlement Request), with the caller\'s own token.\n#\n#   A BILLS request: ONE bill (16 Nov 2026) on the rep\'s open settlement\n#   claim (a running Miscellaneous Expense Claim), scored on save\n#   (custom_bill_status "Checked"). "Send" makes one request per unsent bill,\n#   each with its own chain, so every claim row has its own status and its\n#   own Settlement Request link. The bill keeps its AI score. CEO approval ->\n#   the bill is Verified (sanctioned). A CASH request: an Employee Advance (draft) asked\n#   for; CEO approval -> the request is Verified. Nothing more for now (the\n#   user, 16 Nov 2026): no Accounts Task, no booking, no payment step.\n#   A REJECT, at any step, needs a reason: the request goes back to the rep\n#   (bills to "Checked" with the reason, the advance draft deleted); they fix\n#   and send again. SENT AGAIN (17 Nov 2026): back to whoever rejected it --\n#   the steps approved before stay approved ("Approved before (SR-x)") -- as\n#   long as the bill\'s photo is the same and its amount is not higher; else\n#   from the first approver. resent_from names the rejected request.\n#\n#   NOTHING GETS STUCK (17 Nov 2026), sweep(): a step is SKIPPED when its\n#   approver is no longer active (left, or login disabled) or on approved\n#   leave today, and MOVES UP one level after 2 working days (Sundays not\n#   counted) with no action -- the approver is told -- except a bill read as\n#   High risk (score under 70), which waits. It STOPS AT SM / ZSM (the user,\n#   17 Nov 2026): nothing is ever moved on to a GM or the CEO -- a step whose\n#   next approver is GM / CEO waits, and so does the SM / ZSM step itself.\n#   Runs when a request is sent, after each approval, and hourly\n#   (Server Script "Settlement Escalation", the same sweep()).\n#\n#   GET  action=mine                         the caller\'s requests + their chain\n#   POST action=send_bills   [rows=a,b]      every checked, unsent bill (or just those), one request each\n#   POST action=send_cash    amount, purpose\n#   POST action=withdraw     name            own, while nobody has decided yet\n#   GET  action=queue                        waiting on me / my team / decided by me\n#                                            (overview: IT department, System Manager)\n#   POST action=decide       name, decision (Approve | Reject), note\n#\n# The chain: Employee.reports_to from the requester up, skipping anyone not\n# Active, with no enabled login, or a "Vacant" placeholder, until the CEO. A\n# line that never reaches the CEO gets the CEO added last: the CEO always\n# decides last.\n#\n# safe_exec: no import, no .format(), no set literals, no tuple unpacking,\n# no underscore-prefixed names, no frappe.parse_json -- the chain and the\n# bills are child tables (Settlement Step, Settlement Bill), not JSON.\n\nCEO_USER = "ceo@elbrit.org"\nCEO_DESIGNATION = "Chief Executive Officer"\nOVERVIEW_DEPARTMENTS = ["IT - ELPL"]\nOVERVIEW_ROLES = ["System Manager"]\nLEVELS = ["BE", "ABM", "RBM", "SRBM", "DEPUTY RBM", "SM", "ZSM", "GM"]\n\n\ndef level_of(seat, designation, user, ceo_user, ceo_designation, levels):\n    # "ABM2-AURA-CO-SAL" -> ABM; the CEO -> CEO; a back-office seat -> its designation\n    if user == ceo_user or designation == ceo_designation:\n        return "CEO"\n    head = str(seat or "").split("-")[0]\n    g = ""\n    for ch in head:\n        if not ch.isdigit():\n            g = g + ch\n    g = g.strip().upper()\n    if g in levels:\n        return g\n    return str(designation or g or "Approver")\n\n\ndef chain_of(emp_name, ceo_user, ceo_designation, levels):\n    # [{user, name, level}] up the reporting line, ending with the CEO\n    out = []\n    seen = {}\n    cur = frappe.db.get_value("Employee", emp_name, "reports_to")\n    hops = 0\n    ceo = False\n    while cur and hops < 15 and not ceo:\n        hops = hops + 1\n        if seen.get(cur):\n            break\n        seen[cur] = 1\n        m = frappe.db.get_value("Employee", cur, ["name", "employee_name", "user_id", "status", "custom_role_profile", "designation", "reports_to"], as_dict=True)\n        if not m:\n            break\n        live = m.status == "Active" and m.user_id and str(m.employee_name or "")[:6].lower() != "vacant" and frappe.db.get_value("User", m.user_id, "enabled")\n        if live:\n            lv = level_of(m.custom_role_profile, m.designation, m.user_id, ceo_user, ceo_designation, levels)\n            out.append({"user": m.user_id, "name": m.employee_name, "level": lv})\n            if lv == "CEO":\n                ceo = True\n        cur = m.reports_to\n    if not ceo:\n        name = frappe.db.get_value("Employee", {"user_id": ceo_user, "status": "Active"}, "employee_name") or "CEO"\n        out.append({"user": ceo_user, "name": name, "level": "CEO"})\n    return out\n\n\ndef shape(d):\n    steps = []\n    for s in d.steps or []:\n        steps.append({"user": s.user, "name": s.approver_name, "level": s.level, "decision": s.decision or "",\n                      "at": str(s.decided_on or ""), "note": s.note or ""})\n    bills = []\n    for b in d.bills or []:\n        bills.append({"row": b.row, "date": str(b.bill_date or ""), "title": b.title, "amount": b.amount,\n                      "bill": b.bill or "", "score": b.ai_score, "risk": b.ai_risk or "", "reason": b.ai_reason or ""})\n    # the requester\'s HQ = their seat\'s territory (17 Nov 2026: the approvers\'\n    # list goes HQ > employee), "HQ-Trichy" -> "Trichy"\n    hq = ""\n    seat = frappe.db.get_value("Employee", d.employee, "custom_role_profile", cache=True)\n    if seat:\n        hq = str(frappe.db.get_value("Role Profile", seat, "custom_territory", cache=True) or "")\n    if hq[:3].upper() == "HQ-":\n        hq = hq[3:]\n    resent = None\n    if d.get("resent_from"):\n        pv = frappe.db.get_value("Settlement Request", d.resent_from, ["note", "decided_by"], as_dict=True)\n        if pv:\n            resent = {"from": d.resent_from, "note": pv.note or "",\n                      "by": str(frappe.db.get_value("User", pv.decided_by, "full_name") or pv.decided_by or "")}\n    return {"name": d.name, "hq": hq, "resent": resent, "employee": d.employee, "employee_name": d.employee_name, "user": d.user,\n            "kind": d.kind, "status": d.status, "amount": d.amount, "claim": d.claim or "", "advance": d.advance or "",\n            "purpose": d.purpose or "", "step": d.step, "next_approver": d.next_approver or "", "next_label": d.next_label or "",\n            "note": d.note or "", "decided_by": d.decided_by or "", "decided_on": str(d.decided_on or ""),\n            "creation": str(d.creation), "modified": str(d.modified), "steps": steps, "bills": bills}\n\n\ndef held_up(d, i, now):\n    # why step i of a waiting request should not wait on its approver, else ""\n    st = d.steps[i]\n    m = frappe.db.get_value("Employee", {"user_id": st.user, "status": "Active"}, "name")\n    if not m or not frappe.db.get_value("User", st.user, "enabled"):\n        return "No longer active -- skipped"\n    day = str(now)[:10]\n    if frappe.db.exists("Leave Application", {"employee": m, "status": "Approved", "docstatus": 1,\n                                              "from_date": ["<=", day], "to_date": [">=", day]}):\n        return "On leave -- skipped"\n    for b in d.bills or []:\n        if frappe.utils.flt(b.ai_score) < 70:\n            return ""        # a High-risk bill never skips a level: it waits\n    arrived = frappe.utils.get_datetime(d.creation)\n    if i > 0 and d.steps[i - 1].decided_on:\n        prev = frappe.utils.get_datetime(d.steps[i - 1].decided_on)\n        if prev > arrived:\n            arrived = prev\n    due = arrived\n    n = 0\n    while n < 2:\n        due = frappe.utils.add_days(due, 1)\n        if due.weekday() != 6:\n            n = n + 1\n    if frappe.utils.get_datetime(now) >= due:\n        return "No action in 2 working days -- moved up"\n    return ""\n\n\ndef sweep(d, now, tell):\n    # moves a waiting request past the steps nobody can act on -> True when it\n    # moved (the caller saves). Stops at SM / ZSM: never on to a GM or the CEO.\n    moved = False\n    guard = 0\n    while d.status == "Waiting" and guard < 10:\n        guard = guard + 1\n        i = frappe.utils.cint(d.step)\n        if i >= len(d.steps) - 1:\n            break\n        if str(d.steps[i].level or "").upper() in ["SM", "ZSM"] or str(d.steps[i + 1].level or "").upper() in ["GM", "CEO"]:\n            break\n        why = held_up(d, i, now)\n        if not why:\n            break\n        st = d.steps[i]\n        st.decision = "Skipped"\n        st.decided_on = now\n        st.note = why\n        d.step = i + 1\n        d.next_approver = d.steps[i + 1].user\n        d.next_label = d.steps[i + 1].level\n        moved = True\n        if why[:9] == "No action":\n            notify(st.user, "Moved up to " + str(d.steps[i + 1].approver_name or d.next_approver) + " (no action in 2 working days): "\n                   + str(d.employee_name) + " · " + frappe.utils.fmt_money(d.amount, currency="INR"), d.name)\n    if moved and tell:\n        notify(d.next_approver, ("Settlement" if d.kind == "Bills" else "Cash request") + " to approve: " + str(d.employee_name)\n               + " · " + frappe.utils.fmt_money(d.amount, currency="INR"), d.name)\n    return moved\n\n\ndef last_rejected(row, employee):\n    # the latest request this bill row was in, when it was rejected -> {parent, amount, bill}\n    hits = frappe.db.sql("select parent, amount, bill from `tabSettlement Bill` where `row` = %s and parenttype = \'Settlement Request\' order by creation desc limit 5",\n                         (row,), as_dict=True)\n    for h in hits or []:\n        st = frappe.db.get_value("Settlement Request", h.parent, ["status", "employee"], as_dict=True)\n        if not st or st.status == "Withdrawn":\n            continue\n        if st.status == "Rejected" and st.employee == employee:\n            return h\n        return None\n    return None\n\n\ndef carry(d, old_name):\n    # the steps approved on the rejected request stay approved, up to whoever rejected it\n    old = frappe.get_doc("Settlement Request", old_name)\n    done = {}\n    for st in old.steps or []:\n        if st.decision == "Approved":\n            done[st.user] = st\n    i = 0\n    while i < len(d.steps) - 1 and done.get(d.steps[i].user):\n        o = done.get(d.steps[i].user)\n        d.steps[i].decision = "Approved"\n        d.steps[i].decided_on = o.decided_on\n        d.steps[i].note = "Approved before (" + old_name + ")"\n        i = i + 1\n    if i:\n        d.step = i\n        d.next_approver = d.steps[i].user\n        d.next_label = d.steps[i].level\n\n\ndef notify(user, subject, name):\n    try:\n        frappe.get_doc({"doctype": "Notification Log", "for_user": user, "type": "Alert", "subject": subject,\n                        "document_type": "Settlement Request", "document_name": name}).insert(ignore_permissions=True)\n    except Exception:\n        pass\n\n\nfd = frappe.form_dict\naction = str(fd.get("action") or "mine")\nme = frappe.session.user\nif not me or me == "Guest":\n    frappe.throw("Please log in", frappe.PermissionError)\nemp = frappe.db.get_value("Employee", {"user_id": me, "status": "Active"}, ["name", "employee_name", "department"], as_dict=True)\noverview = me == "Administrator" or bool(emp and emp.department in OVERVIEW_DEPARTMENTS)\nif not overview and frappe.db.exists("Has Role", {"parent": me, "parenttype": "User", "role": ["in", OVERVIEW_ROLES]}):\n    overview = True\n\n\ndef new_request(emp, me, kind, amount, purpose, claim, advance, bills, chain):\n    users = []\n    steps = []\n    for c in chain:\n        users.append(c["user"])\n        steps.append({"user": c["user"], "approver_name": c["name"], "level": c["level"]})\n    d = frappe.get_doc({\n        "doctype": "Settlement Request",\n        "employee": emp.name,\n        "employee_name": emp.employee_name,\n        "user": me,\n        "kind": kind,\n        "status": "Waiting",\n        "amount": amount,\n        "purpose": purpose,\n        "claim": claim,\n        "advance": advance,\n        "step": 0,\n        "next_approver": chain[0]["user"],\n        "next_label": chain[0]["level"],\n        "approvers": "|" + "|".join(users) + "|",\n        "steps": steps,\n        "bills": bills,\n    })\n    d.insert(ignore_permissions=True)\n    return d\n\n\nif action == "mine":\n    rows = []\n    preview = []\n    if emp:\n        for r in frappe.get_all("Settlement Request", filters={"employee": emp.name, "status": ["!=", "Withdrawn"]},\n                                pluck="name", order_by="creation desc", limit_page_length=30):\n            rows.append(shape(frappe.get_doc("Settlement Request", r)))\n        preview = chain_of(emp.name, CEO_USER, CEO_DESIGNATION, LEVELS)\n    frappe.response["message"] = {"requests": rows, "chain": preview, "overview": overview}\n\nelif action == "send_bills":\n    if not emp:\n        frappe.throw("No active employee is linked to this login.")\n    claims = frappe.get_all("Expense Claim", filters={"employee": emp.name, "custom_running": 1, "docstatus": 0},\n                            pluck="name", order_by="creation desc", limit_page_length=20)\n    # rows=a,b: only those bills (the app sends a bill the moment it is added,\n    # 16 Nov 2026 -- so a sent-back bill is not resent before it is fixed)\n    only = []\n    for x in str(fd.get("rows") or "").split(","):\n        if x.strip():\n            only.append(x.strip())\n    claim = None\n    picked = []\n    for c in claims:\n        if frappe.db.exists("Expense Claim Detail", {"parent": c, "parenttype": "Expense Claim", "expense_type": "Food"}):\n            continue\n        rflt = [["parent", "=", c], ["parenttype", "=", "Expense Claim"], ["custom_bill_status", "=", "Checked"],\n                ["custom_settlement", "is", "not set"]]\n        if only:\n            rflt.append(["name", "in", only])\n        rows = frappe.get_all("Expense Claim Detail",\n                              filters=rflt,\n                              fields=["name", "expense_date", "description", "amount", "custom_bill", "custom_ai_score", "custom_ai_risk", "custom_ai_reason"],\n                              order_by="idx asc", limit_page_length=500)\n        if rows:\n            claim = c\n            picked = rows\n            break\n    if not picked:\n        frappe.throw("No checked bills to send -- add a bill, and wait for its check to finish.")\n    chain = chain_of(emp.name, CEO_USER, CEO_DESIGNATION, LEVELS)\n    # 16 Nov 2026 (the user): EACH BILL IS ITS OWN REQUEST, with its own\n    # chain, so every row of the claim carries its own status (and its own\n    # Settlement Request link) and one bill never holds up another.\n    total = 0\n    made = []\n    now = frappe.utils.now()\n    for r in picked:\n        total = total + frappe.utils.flt(r.amount)\n        title = str(r.description or "")[:140]\n        bill = {"row": r.name, "bill_date": r.expense_date, "title": title, "amount": r.amount,\n                "bill": r.custom_bill, "ai_score": r.custom_ai_score, "ai_risk": r.custom_ai_risk, "ai_reason": r.custom_ai_reason}\n        # sent again (17 Nov 2026): back to whoever rejected it, unless the\n        # photo changed or the amount went up (looked up BEFORE the new request\n        # exists -- it would be the latest one with this bill)\n        prev = last_rejected(r.name, emp.name)\n        d = new_request(emp, me, "Bills", r.amount, title or "1 bill", claim, None, [bill], chain)\n        changed = False\n        if prev:\n            d.resent_from = prev.parent\n            if str(prev.bill or "") == str(r.custom_bill or "") and frappe.utils.flt(r.amount) <= frappe.utils.flt(prev.amount) + 0.5:\n                carry(d, prev.parent)\n            changed = True\n        if sweep(d, now, False) or changed:\n            d.save(ignore_permissions=True)\n        frappe.db.set_value("Expense Claim Detail", r.name, {"custom_bill_status": "In Approval", "custom_settlement": d.name, "custom_review_note": None})\n        made.append(d)\n    # the approvers may open the claim and its bill photos (read only)\n    for c in chain:\n        if c["user"] != me and not frappe.db.exists("DocShare", {"share_doctype": "Expense Claim", "share_name": claim, "user": c["user"]}):\n            sh = frappe.get_doc({"doctype": "DocShare", "share_doctype": "Expense Claim", "share_name": claim, "user": c["user"],\n                                 "read": 1, "write": 0, "share": 0, "notify_by_email": 0})\n            sh.flags.ignore_share_permission = True\n            sh.insert(ignore_permissions=True)\n    # one alert per approver for the whole send, not one per bill (a bill\n    # sent again may wait on someone further up)\n    n = len(made)\n    tell = {}\n    for d in made:\n        t = tell.get(d.next_approver) or {"n": 0, "amount": 0, "name": d.name}\n        t["n"] = t["n"] + 1\n        t["amount"] = t["amount"] + frappe.utils.flt(d.amount)\n        tell[d.next_approver] = t\n    for u in tell:\n        t = tell[u]\n        notify(u, str(t["n"]) + (" bill" if t["n"] == 1 else " bills") + " to approve: " + str(emp.employee_name) + " · " + frappe.utils.fmt_money(t["amount"], currency="INR"), t["name"])\n    out = []\n    for d in made:\n        out.append(shape(d))\n    frappe.response["message"] = {"requests": out, "count": n, "amount": total}\n\nelif action == "send_cash":\n    if not emp:\n        frappe.throw("No active employee is linked to this login.")\n    amount = frappe.utils.flt(fd.get("amount"))\n    purpose = " ".join(str(fd.get("purpose") or "").split())[:500]\n    if amount <= 0:\n        frappe.throw("Say how much you need.")\n    if not purpose:\n        frappe.throw("Say what the cash is for.")\n    chain = chain_of(emp.name, CEO_USER, CEO_DESIGNATION, LEVELS)\n    ea = frappe.get_doc({"doctype": "Employee Advance", "employee": emp.name, "posting_date": frappe.utils.today(), "purpose": purpose,\n                         "advance_amount": amount, "currency": "INR", "exchange_rate": 1})\n    ea.flags.settlement = True       # "Employee Advance Task" makes no Accounts Task for it\n    ea.insert(ignore_permissions=True)\n    d = new_request(emp, me, "Cash", amount, purpose, None, ea.name, [], chain)\n    notify(chain[0]["user"], "Cash request to approve: " + str(emp.employee_name) + " · " + frappe.utils.fmt_money(amount, currency="INR"), d.name)\n    frappe.response["message"] = {"request": shape(d)}\n\nelif action == "withdraw":\n    name = str(fd.get("name") or "")\n    d = frappe.get_doc("Settlement Request", name) if name and frappe.db.exists("Settlement Request", name) else None\n    if not d or not emp or d.employee != emp.name:\n        frappe.throw("That is not your request.", frappe.PermissionError)\n    if d.status != "Waiting" or frappe.utils.cint(d.step) > 0:\n        frappe.throw("It can only be taken back before anyone has approved it.")\n    for b in d.bills or []:\n        frappe.db.set_value("Expense Claim Detail", b.row, {"custom_bill_status": "Checked", "custom_settlement": None})\n    if d.advance and frappe.db.get_value("Employee Advance", d.advance, "docstatus") == 0:\n        frappe.delete_doc("Employee Advance", d.advance, ignore_permissions=True, force=True)\n        d.advance = None\n    d.status = "Withdrawn"\n    d.next_approver = None\n    d.next_label = None\n    d.save(ignore_permissions=True)\n    frappe.response["message"] = {"request": shape(d)}\n\nelif action == "queue":\n    waiting = []\n    team = []\n    decided = []\n    since = frappe.utils.add_days(frappe.utils.today(), -60)\n    for r in frappe.get_all("Settlement Request", filters={"status": "Waiting", "next_approver": me}, pluck="name", order_by="creation asc", limit_page_length=200):\n        waiting.append(shape(frappe.get_doc("Settlement Request", r)))\n    flt = {"approvers": ["like", "%|" + me + "|%"], "modified": [">=", since]}\n    if overview:\n        flt = {"modified": [">=", since]}\n    for r in frappe.get_all("Settlement Request", filters=flt, pluck="name", order_by="modified desc", limit_page_length=300):\n        d = frappe.get_doc("Settlement Request", r)\n        if d.status == "Withdrawn" or (d.status == "Waiting" and d.next_approver == me):\n            continue\n        mine_done = False\n        for s in d.steps or []:\n            if s.user == me and s.decision:\n                mine_done = True\n        if mine_done:\n            decided.append(shape(d))\n        elif d.status == "Waiting":\n            team.append(shape(d))\n        elif overview:\n            decided.append(shape(d))\n    frappe.response["message"] = {"waiting": waiting, "team": team, "decided": decided, "overview": overview, "me": me}\n\nelif action == "decide":\n    name = str(fd.get("name") or "")\n    decision = str(fd.get("decision") or "")\n    note = " ".join(str(fd.get("note") or "").split())[:1000]\n    d = frappe.get_doc("Settlement Request", name) if name and frappe.db.exists("Settlement Request", name) else None\n    if not d:\n        frappe.throw("No such request.")\n    if d.status != "Waiting":\n        frappe.throw("This request is already " + str(d.status).lower() + ".")\n    if d.next_approver != me:\n        frappe.throw("This request is waiting on someone else.", frappe.PermissionError)\n    i = frappe.utils.cint(d.step)\n    step = d.steps[i]\n    step.decided_on = frappe.utils.now()\n    step.note = note\n    who = str((emp and emp.employee_name) or me)\n    if decision == "Approve":\n        step.decision = "Approved"\n        if i + 1 < len(d.steps):\n            d.step = i + 1\n            d.next_approver = d.steps[i + 1].user\n            d.next_label = d.steps[i + 1].level\n            # the next approver on leave or gone: straight past them (17 Nov 2026)\n            if not sweep(d, frappe.utils.now(), True):\n                notify(d.next_approver, ("Settlement" if d.kind == "Bills" else "Cash request") + " to approve: " + str(d.employee_name) + " · " + frappe.utils.fmt_money(d.amount, currency="INR"), d.name)\n        else:\n            # the CEO\'s approval is final\n            d.status = "Approved"\n            d.next_approver = None\n            d.next_label = None\n            d.decided_by = me\n            d.decided_on = frappe.utils.now()\n            if d.kind == "Bills":\n                for b in d.bills or []:\n                    amt = frappe.db.get_value("Expense Claim Detail", b.row, "amount")\n                    frappe.db.set_value("Expense Claim Detail", b.row, {"custom_bill_status": "Verified", "sanctioned_amount": amt})\n                if d.claim:\n                    tot = 0\n                    for r in frappe.get_all("Expense Claim Detail", filters={"parent": d.claim, "parenttype": "Expense Claim"}, fields=["sanctioned_amount"], limit_page_length=1000):\n                        tot = tot + frappe.utils.flt(r.sanctioned_amount)\n                    frappe.db.set_value("Expense Claim", d.claim, "total_sanctioned_amount", tot)\n            # 16 Nov 2026 (the user): nothing more for now -- no Accounts Task,\n            # no booking; the CEO\'s approval makes it Verified, and that is all.\n            notify(d.user, ("Your bills are verified" if d.kind == "Bills" else "Your cash request is verified") + " (" + frappe.utils.fmt_money(d.amount, currency="INR") + ")", d.name)\n    elif decision == "Reject":\n        if not note:\n            frappe.throw("Say why it is rejected -- the requester sees it.")\n        step.decision = "Rejected"\n        d.status = "Rejected"\n        d.note = note\n        d.next_approver = None\n        d.next_label = None\n        d.decided_by = me\n        d.decided_on = frappe.utils.now()\n        for b in d.bills or []:\n            frappe.db.set_value("Expense Claim Detail", b.row, {"custom_bill_status": "Checked", "custom_settlement": None,\n                                                               "custom_review_note": ("Returned by " + who + ": " + note)[:500]})\n        if d.advance and frappe.db.get_value("Employee Advance", d.advance, "docstatus") == 0:\n            frappe.delete_doc("Employee Advance", d.advance, ignore_permissions=True, force=True)\n            d.advance = None\n        notify(d.user, "Sent back by " + who + ": " + note, d.name)\n    else:\n        frappe.throw("Approve or Reject?")\n    d.save(ignore_permissions=True)\n    frappe.response["message"] = {"request": shape(d)}\n\nelse:\n    frappe.throw("Unknown action.")\n'
FP_API = '# Server Script "Bill Fingerprint API" -- type API, method bill_fingerprint\n# (12 Nov 2026; matching rewritten 16 Nov 2026). The planner\'s duplicate-bill\n# check.\n#\n# The app server (/api/claims/read-bill) reads a trip bill, checks its type and\n# date, makes its hashes and calls this with the REP\'S OWN token:\n#   action=claim    file_hash, image_hash, content_hash, strong, kind, trip,\n#                   bill_date, amount, vendor, bill_no\n#     -> { ok: 1, name, flag }       the bill is now registered to the rep\n#     -> { ok: 0, reason, matched }  refused; the attempt is recorded too\n#   action=release  name             the rep removed the bill from the trip\n#   action=check    the same as claim, nothing written -> { ok, reason, flag }\n#                   (17 Nov 2026: a settlement bill, the moment it is read)\n#\n# SETTLEMENT BILLS (17 Nov 2026) share this register, kind "Bill": the app\n# checks a settlement bill when it is read (check) and registers it when it\n# is saved (claim, from /api/claims/check). So a bill used on a planner trip\n# is refused as a settlement bill, and the other way round.\n#\n# THE SAME BILL IS REFUSED (16 Nov 2026) -- the read of a bill is not the same\n# letter for letter every time ("INV 2610..." vs "2610...", "13OCT" vs\n# "130CT", the vendor with or without its address, a GSTIN read once and\n# missed once), so bills are compared field by field, not by one exact hash:\n#   1. the same file (SHA-256 of the bytes)\n#   2. the same BILL NUMBER and the same total (within Rs 1), on the same date\n#      -- or on any date when the number is 8+ digits long. Numbers are\n#      compared by their digits: the letters in front dropped, O read as 0,\n#      I / l as 1, then only the digits (bill_key; at least 4 of them)\n#   3. a near-identical photo (6 or fewer of 64 bits differ) with the same\n#      date and total\n#   4. YOUR OWN bill with the same date, total and vendor, when one of the two\n#      has no bill number read\n# Each against every bill used in the last 2 years, the rep\'s own (any trip)\n# and every other employee\'s. FLAGGED only (allowed; the claim goes to\n# Accounts): 4 for another employee\'s bill (two people can eat at one place\n# for the same amount), and a near-identical photo with a different total.\n# Two bills with DIFFERENT numbers are never the same bill.\n# Every refusal is a "Refused" row and a comment on the rep\'s month claim, so\n# the reporting officer sees repeat attempts.\n#\n# Reps cannot read Bill Fingerprint themselves (System Manager / HR Manager\n# only): this script reads with get_all and writes with ignore_permissions.\n# safe_exec: no import, no .format(), no set literals, no tuple unpacking,\n# and a def sees only its own arguments.\n\n\ndef bill_key(s):\n    # "INV 261021IMRTN05360" and "261021IMRTN05360" -> "261021105360";\n    # "UBR-8F2K-13OCT" and "UBR-8F2K-130CT" -> "82130". "" when under 4 digits.\n    t = ""\n    for c in str(s or "").lower():\n        if ("a" <= c <= "z") or ("0" <= c <= "9"):\n            t = t + c\n    i = 0\n    while i < len(t) and "a" <= t[i] <= "z":\n        i = i + 1\n    out = ""\n    for c in t[i:]:\n        if c == "o":\n            out = out + "0"\n        elif c == "i" or c == "l":\n            out = out + "1"\n        elif "0" <= c <= "9":\n            out = out + c\n    out = out.lstrip("0")\n    return out if len(out) >= 4 else ""\n\n\ndef vendor_key(s):\n    t = ""\n    for c in str(s or "").lower():\n        if ("a" <= c <= "z") or ("0" <= c <= "9"):\n            t = t + c\n    return t\n\n\ndef same_vendor(a, b):\n    # "Hotel Saravana Bhavan, T Nagar, Chennai" = "Hotel Saravana Bhavan"\n    if len(a) < 5 or len(b) < 5:\n        return False\n    return a == b or a.startswith(b) or b.startswith(a)\n\n\ndef bits_apart(a, b):\n    if len(a or "") != 16 or len(b or "") != 16:\n        return 64\n    x = int(a, 16) ^ int(b, 16)\n    n = 0\n    while x:\n        x = x & (x - 1)\n        n = n + 1\n    return n\n\n\nfd = frappe.form_dict\naction = str(fd.get("action") or "claim")\nuser = frappe.session.user\nemp = None\nif user and user != "Guest":\n    emp = frappe.db.get_value("Employee", {"user_id": user, "status": "Active"}, "name")\nif not emp:\n    frappe.throw("No active employee is linked to this login.")\n\nif action == "release":\n    name = str(fd.get("name") or "")\n    row = None\n    if name:\n        row = frappe.db.get_value("Bill Fingerprint", name, ["employee", "status"], as_dict=True)\n    if row and row.employee == emp and row.status == "Used":\n        frappe.delete_doc("Bill Fingerprint", name, ignore_permissions=True, force=True)\n        frappe.response["message"] = {"released": name}\n    else:\n        frappe.response["message"] = {"released": None}\n\nelif action == "claim" or action == "check":\n    kind = str(fd.get("kind") or "")\n    if kind not in ["Stay", "Food", "Fuel", "Toll", "Bill"]:\n        frappe.throw("Unknown bill kind.")\n    trip = str(fd.get("trip") or "")[:40]\n    fh = str(fd.get("file_hash") or "").lower()[:64]\n    ih = str(fd.get("image_hash") or "").lower()[:16]\n    ch = str(fd.get("content_hash") or "").lower()[:64]\n    strong = 1 if str(fd.get("strong") or "") in ["1", "true", "True"] else 0\n    bdate = str(fd.get("bill_date") or "")[:10]\n    if len(bdate) != 10:\n        bdate = None\n    amount = frappe.utils.flt(fd.get("amount"))\n    vendor = str(fd.get("vendor") or "")[:140]\n    bill_no = str(fd.get("bill_no") or "")[:140]\n    key = bill_key(bill_no)\n    vkey = vendor_key(vendor)\n    since = frappe.utils.add_days(frappe.utils.today(), -730)\n    cols = ["name", "employee", "trip", "kind", "bill_date", "amount", "vendor", "bill_no", "image_hash"]\n\n    found = []\n    seen = {}\n    if fh:\n        for r in frappe.get_all("Bill Fingerprint", filters={"file_hash": fh, "status": "Used", "creation": [">=", since]}, fields=cols, limit_page_length=0):\n            if not seen.get(r.name):\n                seen[r.name] = 1\n                found.append({"r": r, "hard": 1, "why": "the same file"})\n\n    # every used bill with the same total (any kind: one bill is never two kinds)\n    if amount > 0:\n        for r in frappe.get_all("Bill Fingerprint",\n                                filters={"amount": ["between", [amount - 1, amount + 1]], "status": "Used", "creation": [">=", since]},\n                                fields=cols, limit_page_length=0):\n            if seen.get(r.name):\n                continue\n            same_date = bool(bdate) and str(r.bill_date or "") == bdate\n            rkey = bill_key(r.bill_no)\n            m = None\n            if key and rkey:\n                if key == rkey and (same_date or len(key) >= 8):\n                    m = {"r": r, "hard": 1, "why": "the same bill: bill no " + str(r.bill_no or "") + ", total Rs " + str(int(round(frappe.utils.flt(r.amount))))}\n                # two different bill numbers: two different bills\n            if not m and same_date and ih and bits_apart(ih, r.image_hash) <= 6:\n                m = {"r": r, "hard": 1, "why": "the same photo of the bill"}\n            if not m and same_date and not (key and rkey) and same_vendor(vkey, vendor_key(r.vendor)):\n                if r.employee == emp:\n                    m = {"r": r, "hard": 1, "why": "the same vendor, date and total"}\n                else:\n                    m = {"r": r, "hard": 0, "why": "the same vendor, date and total"}\n            if m:\n                seen[r.name] = 1\n                found.append(m)\n\n    # a near-identical photo with a different total: flagged\n    if ih and bdate and len(ih) == 16:\n        for r in frappe.get_all("Bill Fingerprint", filters={"bill_date": bdate, "status": "Used", "image_hash": ["!=", ""], "creation": [">=", since]}, fields=cols, limit_page_length=0):\n            if not seen.get(r.name) and bits_apart(ih, r.image_hash) <= 6:\n                seen[r.name] = 1\n                found.append({"r": r, "hard": 0, "why": "a near-identical photo"})\n\n    block = None\n    flag = None\n    for m in found:\n        r = m["r"]\n        if r.employee == emp:\n            if r.kind == "Bill":\n                where = "your settlement bills"\n            elif kind != "Bill" and r.trip == trip:\n                where = "this trip"\n            else:\n                where = "your trip of " + str(r.trip or "")[:10]\n            text = "Already claimed on " + where + " (" + m["why"] + ")."\n        else:\n            text = "Already claimed by another employee (" + m["why"] + ")."\n        if m["hard"]:\n            if not block:\n                block = {"name": r.name, "text": text}\n        elif not flag:\n            flag = {"name": r.name, "text": "Possible repeat: " + text}\n\n    base = {\n        "doctype": "Bill Fingerprint",\n        "employee": emp,\n        "kind": kind,\n        "trip": trip,\n        "bill_date": bdate,\n        "amount": amount,\n        "vendor": vendor,\n        "bill_no": bill_no,\n        "file_url": str(fd.get("file_url") or "")[:400],\n        "file_hash": fh,\n        "image_hash": ih,\n        "content_hash": ch,\n        "strong": strong,\n    }\n\n    if action == "check":\n        # nothing written: the settlement form asks before the bill is saved\n        if block:\n            frappe.response["message"] = {"ok": 0, "reason": block["text"], "matched": block["name"]}\n        else:\n            frappe.response["message"] = {"ok": 1, "flag": flag["text"] if flag else None}\n    elif block:\n        base["status"] = "Refused"\n        base["matched"] = block["name"]\n        base["note"] = block["text"]\n        frappe.get_doc(base).insert(ignore_permissions=True)\n        # tell the reporting officer: a comment on the rep\'s claim for the month\n        month = trip[:7]\n        claims = []\n        if kind == "Bill":\n            claims = frappe.get_all("Expense Claim", filters={"employee": emp, "custom_running": 1, "docstatus": 0}, fields=["name"], limit=1)\n        elif len(month) == 7:\n            claims = frappe.get_all("Expense Claim", filters={"employee": emp, "remark": ["like", "Field TA/DA % " + month], "docstatus": ["<", 2]}, fields=["name"], limit=1)\n        if claims:\n            frappe.get_doc({\n                "doctype": "Comment",\n                "comment_type": "Comment",\n                "reference_doctype": "Expense Claim",\n                "reference_name": claims[0].name,\n                "content": "Bill refused (" + kind + ", " + str(bdate or "no date") + ", Rs " + str(amount) + "): " + block["text"] + " See Bill Fingerprint " + block["name"] + ".",\n            }).insert(ignore_permissions=True)\n        frappe.response["message"] = {"ok": 0, "reason": block["text"], "matched": block["name"]}\n    else:\n        base["status"] = "Used"\n        if flag:\n            base["matched"] = flag["name"]\n            base["note"] = flag["text"]\n        doc = frappe.get_doc(base).insert(ignore_permissions=True)\n        frappe.response["message"] = {"ok": 1, "name": doc.name, "flag": flag["text"] if flag else None}\n\nelse:\n    frappe.throw("Unknown action.")\n'
ESCALATION = '# Server Script "Settlement Escalation" -- type Scheduler Event, Cron\n# "20 * * * *" (17 Nov 2026). Hourly: every waiting settlement request whose\n# step cannot wait any longer moves on -- the approver left / disabled / on\n# approved leave today (skipped), or 2 working days with no action (moved up\n# one level, the approver told; a High-risk bill waits). Stops at SM / ZSM:\n# never moved on to a GM or the CEO. The same sweep() as\n# the "Settlement API" script -- copy it from there when it changes\n# (share/src/app/expense-claims/server/settlement_api.py).\n\n\ndef held_up(d, i, now):\n    # why step i of a waiting request should not wait on its approver, else ""\n    st = d.steps[i]\n    m = frappe.db.get_value("Employee", {"user_id": st.user, "status": "Active"}, "name")\n    if not m or not frappe.db.get_value("User", st.user, "enabled"):\n        return "No longer active -- skipped"\n    day = str(now)[:10]\n    if frappe.db.exists("Leave Application", {"employee": m, "status": "Approved", "docstatus": 1,\n                                              "from_date": ["<=", day], "to_date": [">=", day]}):\n        return "On leave -- skipped"\n    for b in d.bills or []:\n        if frappe.utils.flt(b.ai_score) < 70:\n            return ""        # a High-risk bill never skips a level: it waits\n    arrived = frappe.utils.get_datetime(d.creation)\n    if i > 0 and d.steps[i - 1].decided_on:\n        prev = frappe.utils.get_datetime(d.steps[i - 1].decided_on)\n        if prev > arrived:\n            arrived = prev\n    due = arrived\n    n = 0\n    while n < 2:\n        due = frappe.utils.add_days(due, 1)\n        if due.weekday() != 6:\n            n = n + 1\n    if frappe.utils.get_datetime(now) >= due:\n        return "No action in 2 working days -- moved up"\n    return ""\n\n\ndef sweep(d, now, tell):\n    # moves a waiting request past the steps nobody can act on -> True when it\n    # moved (the caller saves). Stops at SM / ZSM: never on to a GM or the CEO.\n    moved = False\n    guard = 0\n    while d.status == "Waiting" and guard < 10:\n        guard = guard + 1\n        i = frappe.utils.cint(d.step)\n        if i >= len(d.steps) - 1:\n            break\n        if str(d.steps[i].level or "").upper() in ["SM", "ZSM"] or str(d.steps[i + 1].level or "").upper() in ["GM", "CEO"]:\n            break\n        why = held_up(d, i, now)\n        if not why:\n            break\n        st = d.steps[i]\n        st.decision = "Skipped"\n        st.decided_on = now\n        st.note = why\n        d.step = i + 1\n        d.next_approver = d.steps[i + 1].user\n        d.next_label = d.steps[i + 1].level\n        moved = True\n        if why[:9] == "No action":\n            notify(st.user, "Moved up to " + str(d.steps[i + 1].approver_name or d.next_approver) + " (no action in 2 working days): "\n                   + str(d.employee_name) + " · " + frappe.utils.fmt_money(d.amount, currency="INR"), d.name)\n    if moved and tell:\n        notify(d.next_approver, ("Settlement" if d.kind == "Bills" else "Cash request") + " to approve: " + str(d.employee_name)\n               + " · " + frappe.utils.fmt_money(d.amount, currency="INR"), d.name)\n    return moved\n\n\ndef last_rejected(row, employee):\n    # the latest request this bill row was in, when it was rejected -> {parent, amount, bill}\n    hits = frappe.db.sql("select parent, amount, bill from `tabSettlement Bill` where `row` = %s and parenttype = \'Settlement Request\' order by creation desc limit 5",\n                         (row,), as_dict=True)\n    for h in hits or []:\n        st = frappe.db.get_value("Settlement Request", h.parent, ["status", "employee"], as_dict=True)\n        if not st or st.status == "Withdrawn":\n            continue\n        if st.status == "Rejected" and st.employee == employee:\n            return h\n        return None\n    return None\n\n\ndef carry(d, old_name):\n    # the steps approved on the rejected request stay approved, up to whoever rejected it\n    old = frappe.get_doc("Settlement Request", old_name)\n    done = {}\n    for st in old.steps or []:\n        if st.decision == "Approved":\n            done[st.user] = st\n    i = 0\n    while i < len(d.steps) - 1 and done.get(d.steps[i].user):\n        o = done.get(d.steps[i].user)\n        d.steps[i].decision = "Approved"\n        d.steps[i].decided_on = o.decided_on\n        d.steps[i].note = "Approved before (" + old_name + ")"\n        i = i + 1\n    if i:\n        d.step = i\n        d.next_approver = d.steps[i].user\n        d.next_label = d.steps[i].level\n\n\ndef notify(user, subject, name):\n    try:\n        frappe.get_doc({"doctype": "Notification Log", "for_user": user, "type": "Alert", "subject": subject,\n                        "document_type": "Settlement Request", "document_name": name}).insert(ignore_permissions=True)\n    except Exception:\n        pass\n\n\nnow = frappe.utils.now()\nmoved = 0\nfor name in frappe.get_all("Settlement Request", filters={"status": "Waiting"}, pluck="name", limit_page_length=2000):\n    d = frappe.get_doc("Settlement Request", name)\n    if sweep(d, now, True):\n        d.save(ignore_permissions=True)\n        moved = moved + 1\n'

def add_option(dt, fieldname, option):
    doc = frappe.get_doc("DocType", dt)
    for f in doc.fields:
        if f.fieldname == fieldname:
            opts = [o for o in str(f.options or "").split("\n")]
            if option in opts:
                print("ok: " + dt + "." + fieldname + " already has " + option)
                return
            print(W + "add option " + option + " to " + dt + "." + fieldname)
            if not DRY:
                f.options = "\n".join(opts + [option])
                doc.save(ignore_permissions=True)
            return
    print("STOP: " + dt + "." + fieldname + " not found")


def add_field(dt, field):
    doc = frappe.get_doc("DocType", dt)
    for f in doc.fields:
        if f.fieldname == field["fieldname"]:
            print("ok: " + dt + "." + field["fieldname"] + " already there")
            return
    print(W + "add field " + dt + "." + field["fieldname"])
    if not DRY:
        doc.append("fields", field)
        doc.save(ignore_permissions=True)


def put_script(name, values):
    if frappe.db.exists("Server Script", name):
        doc = frappe.get_doc("Server Script", name)
        same = (doc.script or "").replace(chr(13), "") == values["script"]
        for k in values:
            if k != "script" and str(doc.get(k) or "") != str(values[k] or ""):
                same = False
        if same and not doc.disabled:
            print("ok: Server Script " + name + " already up to date")
            return
        print(W + "update Server Script " + name + " (" + str(len(doc.script or "")) + " -> " + str(len(values["script"])) + " characters)")
        if not DRY:
            for k in values:
                doc.set(k, values[k])
            doc.disabled = 0
            doc.save(ignore_permissions=True)
    else:
        print(W + "create Server Script " + name)
        if not DRY:
            d = {"doctype": "Server Script", "name": name, "disabled": 0}
            for k in values:
                d[k] = values[k]
            frappe.get_doc(d).insert(ignore_permissions=True)


if not frappe.db.exists("DocType", "Settlement Request") or not frappe.db.exists("DocType", "Bill Fingerprint"):
    print("STOP: run settlement_console.py (and the bill check console) first -- Settlement Request / Bill Fingerprint missing.")
else:
    add_option("Settlement Step", "decision", "Skipped")
    add_field("Settlement Request", {"fieldname": "resent_from", "label": "Sent Again From", "fieldtype": "Link",
                                     "options": "Settlement Request", "read_only": 1, "no_copy": 1,
                                     "description": "The rejected request this bill was sent again from"})
    add_option("Bill Fingerprint", "kind", "Bill")
    put_script("Settlement API", {"script_type": "API", "api_method": "settlement", "script": API})
    put_script("Bill Fingerprint API", {"script_type": "API", "api_method": "bill_fingerprint", "script": FP_API})
    put_script("Settlement Escalation", {"script_type": "Scheduler Event", "event_frequency": "Cron", "cron_format": "20 * * * *", "script": ESCALATION})
    if not DRY:
        # frappe.clear_cache is not allowed in the System Console
        print("done -- now press Clear Cache (user menu > Reload / Clear Cache) once")
